var t=`0779-romazava`;var i=`world-0779`;var a=`MG`;var s=`eastern-africa`;var r=4;var o=89;var g={en:`Romazava`,ua:`Румазава`};var l={en:`Romazava is a Madagascar classic prepared with beef chuck, yellow onion, tomato, ginger root. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Румазава, страва кухні країни Мадагаскар зі складниками: яловича лопатка, жовта цибуля, помідор, корінь імбиру. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,670,`g`],[`sunflower-oil`,45,`ml`],[`yellow-onion`,180,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 60 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 60 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:60,i:[[`tomato`,320,`g`],[`water`,870,`ml`],[`ginger-root`,22,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 14 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 14 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:14,i:[[`spinach`,400,`g`],[`collard-greens`,200,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,16,`g`],[`table-salt`,null,`to_taste`]]}];var m={slug:t,id:i,country:`MG`,region:s,servings:4,minutes:89,title:g,text:l,steps:d};export{a as country,m as default,i as id,o as minutes,s as region,r as servings,t as slug,d as steps,l as text,g as title};